/**
 * Fetch one resource file of a team skill through the bridge, as raw bytes.
 *
 * The bridge answers `files/read` with a JSON envelope: `data.content` holds the
 * file and `data.encoding` says how it is spelled — `base64` for binary,
 * `utf-8` for text. A caller wants the bytes to write to disk, not the envelope,
 * so this decodes `content` and returns a Buffer.
 *
 * Empty is a file, not an error. The bridge signals a miss with a non-zero
 * `code`, never by an empty `content`: a zero-byte resource comes back as
 * `content: ""`. Testing `content` for truthiness — as the proxy's own
 * `files/download` branch does — turns every empty file into a failure. So the
 * only thing read as failure here is `code`.
 *
 * `fetcher` is injectable so tests never touch the network; it defaults to the
 * platform `fetch`. It may resolve to a `Response` (real fetch) or to the
 * already-parsed envelope (a simple stub).
 *
 * Usage:
 *   const bytes = await fetchResource({ skillId, path, bridgeBase });
 */

function decode({ content, encoding } = {}) {
  // `?? ""` matters: a missing or empty content is a zero-byte file, and
  // Buffer.from("", …) is exactly that.
  return encoding === "base64"
    ? Buffer.from(content ?? "", "base64")
    : Buffer.from(content ?? "", "utf-8");
}

export async function fetchResource({ skillId, path, bridgeBase, fetcher = globalThis.fetch }) {
  const url = `${String(bridgeBase ?? "").replace(/\/+$/, "")}/files/read`;
  const res = await fetcher(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path }),
  });

  const envelope = typeof res?.json === "function" ? await res.json() : res;
  const code = envelope?.code;
  if (code != null && Number(code) !== 0) {
    // Carry the envelope's own message through — the reason is in there, and a
    // generic "request failed" would hide it.
    throw new Error(envelope.message ?? `skill files/read failed (code=${code})`);
  }
  return decode(envelope?.data);
}

