/**
 * Fetch one resource file of a team skill from the skill bridge, as raw bytes.
 *
 * The bridge answers `POST <bridgeBase>/files/read` with the usual JSON
 * envelope:
 *
 *   { code: 0, message: "ok", data: { content, encoding, size_bytes, ... } }
 *
 * and `encoding` is either "utf-8" (the content is the text) or "base64" (the
 * content is the file's bytes, base64-encoded). We ask for base64 so a binary
 * resource survives the round trip unchanged.
 *
 * The one thing that is easy to get wrong: an *empty* file is a legal file.
 * Its content is the empty string, and `code` is 0 — so it must decode to a
 * zero-byte Buffer, not be mistaken for a missing field and thrown on. (The
 * bridge's own files/download path makes that mistake: it folds
 * `!parsed.data?.content` into the error branch, so an empty resource comes
 * back as a failure.)
 *
 * `fetcher` is injectable so tests can supply a stub; in production it is the
 * ambient `globalThis.fetch`.
 *
 * @param {string}   skillId    the skill the resource belongs to
 * @param {string}   path       the resource path within the skill
 * @param {string}   bridgeBase base URL of the bridge skill endpoint, e.g.
 *                              http://127.0.0.1:8096/skill-bridge/v3/skill
 * @param {Function} [fetcher]  fetch-compatible HTTP implementation
 * @returns {Promise<Buffer>} the resource's raw bytes
 */
export async function fetchResource({ skillId, path, bridgeBase, fetcher = globalThis.fetch } = {}) {
  if (typeof fetcher !== "function") {
    throw new Error("fetchResource: no fetch implementation available");
  }
  const base = String(bridgeBase ?? "").replace(/\/+$/, "");
  const url = `${base}/files/read`;
  const res = await fetcher(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path, encoding: "base64" }),
  });

  const envelope = await readEnvelope(res);
  if (!envelope || typeof envelope !== "object") {
    throw new Error(`fetchResource: malformed response for ${path}`);
  }
  if (envelope.code !== 0) {
    throw new Error(envelope.message ?? `fetchResource: upstream error (code ${envelope.code})`);
  }

  const data = envelope.data ?? {};
  if (data.content == null) return Buffer.alloc(0);
  const content = String(data.content);
  return Buffer.from(content, data.encoding === "base64" ? "base64" : "utf-8");
}

/** Parse a Response-like into the JSON envelope, tolerating a stub with only json() or only text(). */
async function readEnvelope(res) {
  if (res && typeof res.text === "function") {
    const raw = await res.text();
    try {
      return JSON.parse(raw);
    } catch {
      throw new Error(`fetchResource: upstream returned non-JSON body: ${raw.slice(0, 200)}`);
    }
  }
  if (res && typeof res.json === "function") return res.json();
  throw new Error("fetchResource: response has neither text() nor json()");
}


